package blockbranch.realistic;
import java.nio.file.*;import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.levelgen.structure.templatesystem.*;
/** Bounded final planner costs and native model/construction contracts. */
public final class SnowShelterSurvey {
 public static void register(){net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents.SERVER_STARTED.register(server->{try{
  var level=server.overworld();var g=(RealisticGenerator)level.getChunkSource().getGenerator();var random=level.getChunkSource().randomState();var bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();long id=Thread.currentThread().threadId(),cpu=bean.getCurrentThreadCpuTime(),bytes=bean.getThreadAllocatedBytes(id),start=System.nanoTime();var planner=SnowShelters.bind(level.getSeed(),g,random);long bound=System.nanoTime()-start;var out=new LinkedHashMap<String,Object>();out.put("seed",level.getSeed());out.put("regionMaskGrid",2048);out.put("regions",planner.regionCount());out.put("candidateCells",planner.candidateCount());out.put("bindWallNanos",bound);out.put("bindThreadCpuNanos",bean.getCurrentThreadCpuTime()-cpu);out.put("bindThreadAllocatedBytes",bean.getThreadAllocatedBytes(id)-bytes);out.put("serializedIndexBytes",SnowShelters.CODEC.encodeStart(com.mojang.serialization.JsonOps.INSTANCE,planner).getOrThrow().toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length);write("snow-bind.json",out);
  var rows=new ArrayList<Object>();for(var region:java.util.stream.Stream.concat(planner.ordered(BlockPos.ZERO,6000000).stream().limit(4),planner.ordered(new BlockPos(0,0,-1900000),6000000).stream().limit(8)).distinct().toList()){
   cpu=bean.getCurrentThreadCpuTime();bytes=bean.getThreadAllocatedBytes(id);start=System.nanoTime();var p=region.plan();var row=new LinkedHashMap<String,Object>();row.put("owner",region.owner());row.put("wallNanos",System.nanoTime()-start);row.put("threadCpuNanos",bean.getCurrentThreadCpuTime()-cpu);row.put("threadAllocatedBytes",bean.getThreadAllocatedBytes(id)-bytes);row.put("accepted",p.isPresent());p.ifPresent(plan->row.put("plan",plan));rows.add(row);write("snow-regions.json",rows);
  }
  out.put("firstFourRegions",rows);out.put("nativeTemplateChecks",templates(net.minecraft.world.level.levelgen.structure.pieces.StructurePieceSerializationContext.fromLevel(level).structureTemplateManager()));write("snow-survey.json",out);Files.writeString(Path.of("snow-result.txt"),"PASS bounded regional feasibility and native template semantics");
 }catch(Throwable t){blockbranch.Blockbranch.LOGGER.error("SNOW_SURVEY_FAIL",t);try{Files.writeString(Path.of("snow-result.txt"),"FAIL "+t);}catch(Exception ignored){}}finally{server.halt(false);}});}
 private static Object templates(StructureTemplateManager manager){
  var rows=new ArrayList<Object>();for(int variant=0;variant<2;variant++)for(var rotation:Rotation.values()){
   var t=manager.getOrCreate(blockbranch.Blockbranch.id("igloo/snow_shelter_v1_"+variant));require(t.getSize().equals(new net.minecraft.core.Vec3i(7,6,8)),"Current-format native template size");var settings=new StructurePlaceSettings().setRotation(rotation).setRotationPivot(new BlockPos(3,5,5));
   var plan=new SnowShelters.Plan(3,0,5,rotation.ordinal(),variant,0);for(int z=0;z<8;z++)for(int y=0;y<6;y++)for(int x=0;x<7;x++)require(plan.local(x,y,z).equals(StructureTemplate.calculateRelativePosition(settings,new BlockPos(x,y,z))),"Exact primitive rotation agrees with native template coordinates");
   require(t.filterBlocks(BlockPos.ZERO,settings,Blocks.BED.red()).size()==2,"Native bed pair retained");require(t.filterBlocks(BlockPos.ZERO,settings,Blocks.FURNACE).size()==1,"One furnace");require(t.filterBlocks(BlockPos.ZERO,settings,Blocks.CRAFTING_TABLE).size()==1,"One workbench");require(t.filterBlocks(BlockPos.ZERO,settings,Blocks.REDSTONE_TORCH).size()==1,"Native low-light torch");require(t.filterBlocks(BlockPos.ZERO,settings,Blocks.OAK_TRAPDOOR).isEmpty(),"Overlay does not replace native shaft decision");rows.add(Map.of("variant",variant,"rotation",rotation.toString(),"size",t.getSize().toShortString()));
  }
  int basements=0,noBasement=0;for(int seed=0;seed<8;seed++)for(var rotation:Rotation.values()){
   var builder=new net.minecraft.world.level.levelgen.structure.pieces.StructurePiecesBuilder();net.minecraft.world.level.levelgen.structure.structures.IglooPieces.addPieces(manager,new BlockPos(5,90,3),rotation,builder,net.minecraft.util.RandomSource.create(OakBirchWoodland.mix(seed)));var pieces=builder.build().pieces();if(pieces.size()>1){basements++;require(pieces.size()>=5&&pieces.size()<=12,"Native 4..11 shaft segments plus top/bottom");}else noBasement++;
   for(var piece:pieces){var b=piece.getBoundingBox();require(b.minX()>=0&&b.maxX()<16&&b.minZ()>=0&&b.maxZ()<16,"Native original pieces contained in start chunk for all rotations");}
  }
  require(basements>0&&noBasement>0,"Both native random branches observed");var bottom=manager.getOrCreate(net.minecraft.resources.Identifier.withDefaultNamespace("igloo/bottom"));var tag=bottom.save(new net.minecraft.nbt.CompoundTag());require(tag.getListOrEmpty("entities").size()==2,"Native laboratory retains its two original resident template entities");require(bottom.filterBlocks(BlockPos.ZERO,new StructurePlaceSettings(),Blocks.BREWING_STAND).size()==1,"Native brewing station retained");return Map.of("overlays",rows,"nativeBasementCases",basements,"nativeNoBasementCases",noBasement,"originalBottomEntities",2,"scope","Templates and native construction only; no placement, resident spawn/save or render claim");
 }
 private static void write(String name,Object value)throws Exception{Files.writeString(Path.of(name),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(value));}
 private static void require(boolean b,String message){if(!b)throw new AssertionError(message);}
}
